INSERT INTO chunks (url, title, lang, published, chunk_index, content, embedding) VALUES ('https://alexisalulema.com/blog/activation-functions-in-tensorflow/', 'Activation Functions (updated)', 'en', '2017-10-15', 9, 'SELU is an activation function that induces self-normalizing properties that converges to zero mean and unit variance. Unlike ReLU, it can reach values below 0, which allows the neural network to have an output of mean 0, and this feature helps the model to converge more quickly towards the solution. Example: import tensorflow as tf
import matplotlib.pyplot as plt
X = tf.linspace(-7., 7., 100)
y = tf.keras.activations.selu(X)
plt.plot(X,y)
plt.grid() Example: import torch
import matplotlib.pyplot as plt
X = torch.linspace(-7., 7., steps=100)
y = torch.nn.SELU()(X)
plt.plot(X,y)
plt.grid() See it at Google Colab here: Activation Functions', '[-0.118003,-0.020847,-0.054923,0.033029,-0.005731,-0.002968,0.061758,0.013619,-0.022889,0.035178,0.114363,-0.027335,0.025722,0.006282,-0.079707,0.010655,0.000930,0.015777,-0.109426,-0.053182,0.069928,-0.068141,-0.091439,-0.006826,-0.016468,-0.001485,-0.030125,-0.042745,0.063023,-0.099800,0.091110,0.078259,-0.006251,0.026463,-0.046979,0.011933,0.015310,0.006200,-0.007622,0.012507,-0.063364,0.049867,-0.045043,0.019334,0.038855,-0.092465,0.039368,-0.059514,-0.048084,-0.025415,-0.028862,0.060856,0.021842,-0.019414,0.030749,0.011585,-0.019361,0.025086,0.056523,-0.053941,0.039786,0.069327,-0.068265,0.026042,0.051330,-0.054556,0.076013,0.009727,0.034408,0.011638,-0.035179,-0.032552,0.019831,-0.037259,0.002297,0.003001,0.029976,0.041303,0.031837,-0.006677,0.108908,-0.007447,0.051365,0.093327,0.048412,0.069778,0.042454,-0.053119,0.049964,-0.071709,0.127373,-0.039760,-0.130721,0.060211,0.044417,0.001923,-0.000491,-0.022192,0.050824,0.125970,-0.018385,0.036303,0.028781,0.049458,-0.023694,-0.068765,0.022815,0.066204,-0.010058,0.004344,0.034844,-0.049121,-0.043546,-0.017420,0.037683,-0.090096,-0.052277,-0.010665,0.069003,0.025736,-0.021142,-0.002988,0.002311,0.112431,0.070548,-0.064430,-0.033223,-0.043097,0.025258,0.024788,-0.008389,0.006249,-0.000409,-0.026057,0.014791,0.016368,-0.022821,0.034554,-0.046710,0.046095,0.026574,0.098613,0.060719,0.025662,0.050909,0.033868,0.050001,-0.074133,0.005203,-0.043937,-0.007655,-0.161974,-0.023299,0.002536,0.003036,0.030363,-0.019611,0.056542,0.017599,0.006820,-0.064551,0.082183,-0.089495,-0.019896,0.030245,0.028243,0.002485,0.052440,-0.066922,0.097072,-0.004479,-0.023772,-0.031647,-0.022945,0.042974,-0.011231,-0.051336,-0.059701,-0.062526,0.037596,0.089766,-0.014397,0.034222,0.013438,-0.030420,0.001061,0.020408,0.040867,-0.080363,-0.037351,-0.054392,-0.017622,0.057599,0.029839,-0.112758,-0.087263,0.102938,0.027606,-0.031933,0.018706,-0.038371,-0.068854,0.010594,-0.073019,-0.02