INSERT INTO chunks (url, title, lang, published, chunk_index, content, embedding) VALUES ('https://alexisalulema.com/blog/cholesky-decomposition-for-linear-regression-with-tensorflow/', 'Cholesky Decomposition for Linear Regression with TensorFlow', 'en', '2018-01-20', 1, 'Finally, linear regression through Cholesky decomposition is analogous to Linear Least Squares, but reduced to solving a system of linear equations. Cholesky Decomposition is already implemented in TensorFlow, PyTorch, or NumPy, however, you can review more details about Cholesky Decomposition . TensorFlow PyTorch Numpy TensorFlow import matplotlib.pyplot as plt
import tensorflow as tf
import numpy as np
# Generate data
x_vals = np.linspace(start=0, stop=10, num=100)
y_vals = x_vals + np.random.normal(loc=0, scale=1, size=100)
x_vals_column = np.transpose(np.matrix(x_vals))
ones_column = np.transpose(np.matrix(np.repeat(a=1, repeats=100)))
X = np.column_stack((x_vals_column, ones_column))
Y = np.transpose(np.matrix(y_vals))
X_tensor = tf.constant(X, dtype=tf.float64)
Y_tensor = tf.constant(Y, dtype=tf.float64)
# Perform computations
tX_X = tf.matmul(tf.transpose(X_tensor), X_tensor)
L = tf.linalg.cholesky(tX_X)
tX_Y = tf.matmul(tf.transpose(X_tensor), Y_tensor)
sol1 = tf.linalg.solve(L, tX_Y)
sol2 = tf.linalg.solve(tf.transpose(L), sol1)
# Extract coefficients
solution_eval = sol2.numpy()
m_slope = solution_eval[0][0]
b_intercept = solution_eval[1][0]
print(''slope (m): '' + str(m_slope))
print(''intercept (b): '' + str(b_intercept))
# Visualization
best_fit = []
for i in x_vals:
best_fit.append(m_slope * i + b_intercept)
plt.plot(x_vals, y_vals, ''o'', label=''Data'')
plt.plot(x_vals, best_fit, ''r-'', label=''Linear Regression'', linewidth=3)
plt.legend(loc=''upper left'')
plt.show() PyTorch', '[-0.080649,-0.061024,0.010603,-0.016523,-0.000847,-0.003923,0.022871,0.063572,-0.037582,0.027076,0.073776,-0.041513,0.097219,-0.038480,-0.095667,0.033205,-0.059931,0.027532,-0.033570,-0.017716,0.013088,-0.038405,-0.090442,0.020227,-0.032806,0.036936,-0.033500,-0.023017,0.011885,-0.091521,0.078537,0.118268,-0.014030,-0.016120,0.019052,-0.015356,-0.099404,0.015065,0.011733,0.075776,-0.061589,0.011221,0.031465,-0.018174,0.023297,-0.077582,-0.054606,0.003979,-0.074040,-0.024298,-0.065677,0.065539,-0.044823,-0.022447,-0.031799,0.053069,0.020014,-0.044622,-0.016259,-0.060970,0.068236,0.042922,-0.086975,-0.001916,0.072656,0.059905,0.118714,-0.006142,0.103394,0.124688,-0.048393,0.053238,-0.037987,-0.040872,-0.011636,-0.007923,0.012894,0.040138,0.047887,-0.024729,0.040388,0.014827,0.007402,-0.002020,0.019102,0.032761,0.069257,0.034749,0.053060,-0.027109,0.107120,0.007985,-0.150290,0.032346,0.014680,0.041502,-0.011992,0.004646,0.087214,0.140349,-0.053941,0.013136,-0.014217,0.017293,-0.078519,-0.015564,0.003225,-0.020322,-0.024662,0.004671,0.007339,0.009401,-0.028730,0.023496,0.070584,-0.095472,0.008702,-0.017617,0.029926,0.034285,-0.019086,0.044729,-0.003195,0.171995,0.111224,-0.087067,-0.046654,-0.056692,0.022201,-0.044033,0.049385,-0.072283,0.002272,0.068588,-0.008099,-0.030202,0.012087,0.067738,-0.033003,0.031390,-0.051141,0.031778,-0.003774,0.001779,0.063434,0.083485,-0.044920,-0.072245,0.023817,-0.016801,0.011889,-0.118940,-0.029808,-0.005406,-0.073106,0.036776,0.028036,-0.011318,0.015648,0.030034,-0.083415,0.073291,0.016602,-0.015274,0.036299,0.020040,0.010302,0.023056,-0.057467,0.065296,0.088721,-0.022556,-0.045512,-0.017555,0.072446,0.009022,-0.082731,-0.035566,-0.019182,0.019956,0.025976,-0.028607,0.005654,0.018095,-0.086048,-0.015907,0.039779,0.047043,-0.098166,-0.054672,-0.034556,-0.075311,0.042713,0.006837,-0.111978,-0.103505,0.139585,0.061443,-0.014510,-0.005198,-0.012323,0.044702,0.063270,-0.042023,0.038319,0.024068,-0.023705,-0.093843,-0.0