INSERT INTO chunks (url, title, lang, published, chunk_index, content, embedding) VALUES ('https://alexisalulema.com/blog/cholesky-decomposition-for-linear-regression-with-tensorflow/', 'Cholesky Decomposition for Linear Regression with TensorFlow', 'en', '2018-01-20', 2, 'PyTorch import matplotlib.pyplot as plt
import torch
import numpy as np
# Generate data
x_vals = np.linspace(start=0, stop=10, num=100)
y_vals = x_vals + np.random.normal(loc=0, scale=1, size=100)
x_vals_column = np.transpose(np.matrix(x_vals))
ones_column = np.transpose(np.matrix(np.repeat(a=1, repeats=100)))
X = np.column_stack((x_vals_column, ones_column))
Y = np.transpose(np.matrix(y_vals))
X_tensor = torch.tensor(X, dtype=torch.float64)
Y_tensor = torch.tensor(Y, dtype=torch.float64)
# Perform computations
tX_X = torch.mm(X_tensor.T, X_tensor)
L = torch.cholesky(tX_X)
tX_Y = torch.mm(X_tensor.T, Y_tensor)
sol = torch.cholesky_solve(tX_Y, L)
# Extract coefficients
m_slope = sol[0][0].item()
b_intercept = sol[1][0].item()
print(''slope (m): '' + str(m_slope))
print(''intercept (b): '' + str(b_intercept))
# Visualization
best_fit = []
for i in x_vals:
best_fit.append(m_slope * i + b_intercept)
plt.plot(x_vals, y_vals, ''o'', label=''Data'')
plt.plot(x_vals, best_fit, ''r-'', label=''Linear Regression'', linewidth=3)
