INSERT INTO chunks (url, title, lang, published, chunk_index, content, embedding) VALUES ('https://alexisalulema.com/blog/cholesky-decomposition-for-linear-regression-with-tensorflow/', 'Cholesky Decomposition for Linear Regression with TensorFlow', 'en', '2018-01-20', 3, 'Numpy import matplotlib.pyplot as plt
import numpy as np
# Generate data
x_vals = np.linspace(start=0, stop=10, num=100)
y_vals = x_vals + np.random.normal(loc=0, scale=1, size=100)
x_vals_column = np.transpose(np.matrix(x_vals))
ones_column = np.transpose(np.matrix(np.repeat(a=1, repeats=100)))
X = np.column_stack((x_vals_column, ones_column))
Y = np.transpose(np.matrix(y_vals))
# Perform computations using Cholesky Decomposition
tX_X = np.dot(X.T, X)
L = np.linalg.cholesky(tX_X)
tX_Y = np.dot(X.T, Y)
sol = np.linalg.solve(L, tX_Y)
beta = np.linalg.solve(L.T, sol)
# Extract coefficients
m_slope = beta[0,0]
b_intercept = beta[1,0]
print(''slope (m): '' + str(m_slope))
print(''intercept (b): '' + str(b_intercept))
# Visualization
best_fit = []
for i in x_vals:
best_fit.append(m_slope * i + b_intercept)
plt.plot(x_vals, y_vals, ''o'', label=''Data'')
plt.plot(x_vals, best_fit, ''r-'', label=''Linear Regression'', linewidth=3)
plt.legend(loc=''upper left'')
plt.show() slope (m): 1.0830263227926582 intercept (b): -0.3348165868955632 As you can see, this solution is very similar to Linear Least Squares, but this decomposition is sometimes much more efficient and numerically stable.', '[-0.085229,-0.081134,-0.012228,-0.030286,-0.009014,0.001409,0.009734,0.053328,-0.031717,0.020797,0.083192,-0.039869,0.094918,-0.004167,-0.084495,0.038317,-0.036123,0.026443,-0.043657,-0.031685,-0.004993,-0.046449,-0.062745,0.050374,-0.020047,0.052247,-0.033835,-0.016755,-0.003642,-0.078722,0.067645,0.086218,0.017509,-0.017409,-0.002101,0.003738,-0.102094,0.031916,0.016108,0.062359,-0.083654,0.048027,0.050264,-0.003702,0.052108,-0.051075,-0.057168,-0.007953,-0.051196,-0.015987,-0.069280,0.036768,-0.058944,-0.020890,-0.010559,0.027753,0.001959,-0.035189,-0.007130,-0.025809,0.081636,0.033498,-0.068206,-0.009572,0.076249,0.058316,0.145563,-0.043637,0.082867,0.129134,-0.065288,0.038262,-0.015319,-0.055060,-0.018461,-0.017432,0.016793,0.035408,0.024003,-0.009295,0.036780,0.008167,0.022160,-0.014078,0.008455,0.021910,0.067676,0.035653,0.072077,-0.045031,0.105789,0.018402,-0.173610,0.034893,0.018611,0.042569,-0.015381,0.002539,0.088232,0.158742,-0.054188,0.006440,-0.040963,-0.009439,-0.065152,-0.006596,0.028994,-0.002604,-0.026760,0.036571,0.029780,0.000619,-0.015525,0.046752,0.098804,-0.099688,-0.001348,-0.007957,0.019084,0.037964,0.002732,0.019637,0.015339,0.155788,0.100923,-0.106521,-0.021921,-0.050268,0.004314,-0.012589,0.059604,-0.044815,0.002515,0.052530,-0.029000,-0.020070,0.000986,0.080561,-0.049431,0.031359,-0.054571,0.076619,0.006358,0.013567,0.078945,0.072044,-0.063508,-0.042498,0.037395,-0.065660,0.016503,-0.109225,-0.037578,-0.011654,-0.058781,0.041727,0.023084,0.001901,-0.007959,0.016866,-0.096036,0.058073,0.027387,-0.029762,0.047258,0.037152,0.005466,0.001492,-0.072120,0.069490,0.076699,-0.068188,-0.018797,-0.012433,0.080351,0.016818,-0.052375,-0.018564,-0.014566,0.026057,0.000407,-0.037959,0.011571,0.030660,-0.066253,-0.004277,0.004