INSERT INTO chunks (url, title, lang, published, chunk_index, content, embedding) VALUES ('https://alexisalulema.com/blog/installing-sql-server-for-linux-on-docker-container/', 'Installing SQL Server for Linux on Docker Container', 'en', '2017-01-17', 0, 'It is very common requiring MS SqlServer if you are developing ASP.NET web applications; because of this, having a local Sql Server is a great plus if you are developing web apps on ASP.NET Core on Mac, or Linux. One of the things to take in consideration is that we can make a “clean and rapid installation” using a Docker container. Take a look at this video for instructions! Installing Docker Installing Kitematic Installing and using SQL Server Client (sql-cli) Installing mssql extension on VSCode Configuring connection on VSCode https://youtu.be/48ziuJpo0jI', '[0.028196,-0.071875,-0.067511,0.018105,-0.052150,0.017024,-0.124913,-0.060954,-0.046822,0.021489,-0.031248,0.027687,0.070412,-0.046546,0.016468,0.009083,0.032329,-0.040702,-0.034137,0.027844,-0.093064,-0.066512,0.027295,-0.030364,-0.015302,-0.043663,-0.008614,0.021717,0.038474,0.018834,0.027222,0.005333,-0.088535,-0.044181,-0.019921,-0.036407,0.035639,-0.060196,-0.093388,0.019077,0.043773,0.096104,-0.023963,0.005479,-0.056928,-0.067003,-0.070787,-0.020053,-0.001498,-0.063154,-0.050023,0.003999,-0.052402,0.020968,-0.078635,0.037418,-0.014130,0.058245,-0.131507,0.033301,0.046885,-0.061750,0.045832,0.054406,-0.041953,0.010812,0.022758,0.095287,0.032682,-0.103555,-0.151087,0.016461,-0.115089,0.014406,-0.043712,-0.001762,0.040379,-0.052569,0.138872,0.007815,-0.024719,0.024899,-0.009562,0.044478,0.004966,-0.004910,-0.066678,-0.024403,0.016373,-0.054776,0.006589,-0.059121,-0.047115,0.019823,0.008100,-0.016594,-0.033982,0.054878,-0.019801,0.053224,-0.063249,-0.093884,-0.089663,-0.001454,0.057592,0.010773,0.080617,0.031274,0.043747,-0.052023,-0.006024,0.016901,-0.055979,-0.020827,-0.032884,0.083437,-0.092661,-0.074477,-0.021272,-0.026957,-0.057134,0.001894,-0.030863