INSERT INTO chunks (url, title, lang, published, chunk_index, content, embedding) VALUES ('https://alexisalulema.com/blog/javascript-levenshtein-algorithm-implementation/', 'JavaScript Levenshtein Algorithm Implementation', 'en', '2021-09-08', 1, 'In conclusion, using this algorithm depends on your scenario. For most of the times I needed it, I had to use it in the browser, so here is it in Javascript: class LevenshteinModel {
compute(first: string, second: string): number {
if (first.length == 0)
return second.length;
if (second.length == 0)
return first.length;
let current = 1;
let previous = 0;
let r: number[][] = [[], []];
for (let i = 0; i <= second.length; i++)
r[previous][i] = i;
for (let i = 0; i < first.length; i++) {
r[current][0] = i + 1;
for (let j = 1; j <= second.length; j++) {
const cost = (second[j - 1] === first[i]) ? 0 : 1;
r[current][j] = Math.min(
r[previous][j] + 1,
r[current][j - 1] + 1,
r[previous][j - 1] + cost);
}
previous = (previous + 1) % 2;
current = (current + 1) % 2;
}
const weight = r[previous][second.length];
return weight;
}
} If you think this content was helpful, consider buy me a cup of coffee. ;) ☕👉', '[-0.086009,0.008189,-0.017594,0.064545,-0.037599,0.002109,0.052385,0.070910,0.011907,-0.026916,0.030190,-0.053890,0.020914,0.046535,-0.022461,-0.035467,0.009622,0.015027,-0.087027,-0.009542,0.042503,-0.019626,-0.032083,-0.018635,0.011639,0.007416,0.006239,0.026693,0.024613,-0.057133,0.066477,-0.016708,0.022631,-0.022423,-0.041513,0.011619,-0.003715,-0.028166,0.015228,0.144232,-0.075984,0.054582,-0.020748,-0.008047,0.055796,0.005834,-0.079090,-0.058362,-0.010173,0.011706,0.025759,0.039566,-0.098229,0.008858,0.025684,0.062757,-0.037669,-0.137644,-0.100676,-0.041415,0.005703,-0.065820,0.004166,0.023709,0.022322,0.022398,0.049518,-0.036138,0.107343,0.085707,-0.059290,-0.002069,-0.079171,-0.076273,-0.030529,-0.021838,0.032970,0.022092,0.096933,-0.039242,0.022554,-0.076557,-0.039692,-0.011177,0.044445,0.030350,0.057016,0.013485,0.021600,0.000317,0.024816,0.041095,-0.085096,0.065491,-0.020739,0.003993,-0.013995,-0.010812,0.037729,0.180056,-0.101550,-0.022825,-0.050410,-0.043400,-0.041009,0.002147,-0.006524,0.015091,0.029216,-0.002692,0.021237,0.041669,0.030044,0.158824,-0.003375,-0.035739,0.094827,-0.077057,0.052373,0.044169,0.011797,0.026101,-0.034393,0.040724,0.021420,-0.153922,0.002494,-0.122182,-0.040120,-0.074972,0.063933,-0.024472,-0.028855,0.122842,-0.010377,-0.024696,-0.030936,0.018094,-0.032916,0.055006,0.003212,0.074720,-0.058955,-0.035027,0.039434,0.075061,-0.037953,-0.011536,0.026719,-0.004627,0.056949,-0.057516,-0.052334,-0.036123,-0.015338,-0.084923,0.027694,-0.069209,0.010873,-0.002652,-0.130221,0.059095,0.013372,-0.060182,0.078016,0.063370,0.069287,0.048960,-0.036008,0.017863,0.116414,-0.005381,-0.091743,-0.015453,0.045714,0.020980,-0.113067,0.010372,-0.024032,0.031076,0.001398,0.012719,-0.007142,-0.050358,-0.099540,0.050178,0.017242,0.019680,-0.075027,0.025755,0.057101,-0.113144,-0.012311,0.018082,-0.070647,-0.059097,0.126663,0.071218,0.035907,-0.028642,-0.049424,0.023882,0.