INSERT INTO chunks (url, title, lang, published, chunk_index, content, embedding) VALUES ('https://alexisalulema.com/blog/understanding-variables-and-placeholders-in-tensorflow/', 'Understanding Variables and Placeholders in TensorFlow', 'en', '2017-10-11', 1, 'Placeholders are just holding the position for data to be fed into the graph. To put a placeholder in the graph, we must perform at least one operation on the placeholder. sess = tf.Session()
x = tf.placeholder(tf.float32, shape=[2, 2])
# y is the operation to run on x placeholder
y = tf.identity(x)
# x_vals is data to feed into the x placeholder
x_vals = np.random.rand(2, 2)
# Runs y operation
sess.run(y, feed_dict={x: x_vals}) TensorFlow will not return a self-referenced placeholder in the feed dictionary. With these concepts clear, we can move forward with TensorFlow. See you next time with more TF!', '[-0.065557,-0.028561,0.025560,-0.040225,-0.025210,-0.014049,0.027382,0.024431,-0.055589,-0.042557,0.096690,-0.035393,0.064490,0.024050,-0.046941,-0.053341,0.011408,0.019454,-0.001681,-0.011987,0.021216,-0.038741,-0.058884,0.000158,-0.068653,0.005542,-0.058799,-0.006222,0.063894,-0.107934,0.084802,-0.004163,-0.048962,0.042117,-0.031042,0.013101,-0.028020,-0.003381,-0.030465,0.062682,-0.059815,0.009127,-0.003952,-0.010056,-0.008217,-0.055491,0.051722,0.017260,-0.079560,-0.004403,-0.031826,0.036024,-0.010200,0.019848,-0.004711,0.071147,0.072251,-0.049225,0.004170,0.004293,0.046083,-0.043488,-0.079310,-0.003316,0.045109,-0.029170,0.059860,0.000470,0.052211,0.034544,0.046384,0.037284,-0.041367,0.021250,-0.017476,0.074349,-0.062248,0.029756,0.118076,-0.048952,0.011669,-0.006462,0.032367,-0.021485,-0.075797,0.054994,0.054631,0.020087,0.007548,0.002957,0.110192,0.025290,-0.035862,-0.001085,0.017080,0.003275,-0.041627,0.072026,0.043044,0.089580,-0.062043,0.015126,-0.074734,0.026011,0.035337,-0.044039,-0.077550,-0.058828,0.019841,0.041348,-0.022676,-0.014185,-0.012954,0.011736,-0.067564,-0.090977,-0.005630,-0.060328,0.075075,0.011152,-0.013442,0.035944,-0.057412,0.091176,0.079000,-0.069255,-0.045033,-0.044754,-0.007841,-0.057989,0.071824,-0.068699,-0.016868,0.016261,-0.040723,0.004474,-0.053087,0.027231,-0.027667,-0.031987,-0.023941,0.082872,0.036690,0.039067,0.059790,0.055264,0.073906,-0.096039,-0.015100,-0.001056,-0.039042,-0.047022,-0.048992,-0.004291,-0.083708,-0.017504,0.004219,-0.011617,-0.001193,-0.067569,-0.055394,0.094553,0.019227,-0.090560,0.102973,0.025517,-0.027212,-0.045185,-0.025653,0.007305,0.011468,0.001398,-0.121100,-0.046097,0.033519,-0.017846,-0.036946,-0.089518,0.001567,0.011238,0.053553,-0.073241,-0.006470,-0.017155,-0.096039,-0.040469,-0.01314