INSERT INTO chunks (url, title, lang, published, chunk_index, content, embedding) VALUES ('https://alexisalulema.com/es/blog/descomposicion-cholesky-para-regresion-lineal/', 'Descomposición Cholesky para Regresión Lineal', 'es', '2023-10-03', 1, 'La descomposición Cholesky ya está implementada en TensorFlow, PyTorch o NumPy, sin embargo, en este link puedes revisar más detalles de Descomposición Cholesky . Ahora, vamos a ver un ejemplo de su utilización: TensorFlow PyTorch Numpy TensorFlow import matplotlib.pyplot as plt
import tensorflow as tf
import numpy as np
# Generate data
x_vals = np.linspace(start=0, stop=10, num=100)
y_vals = x_vals + np.random.normal(loc=0, scale=1, size=100)
x_vals_column = np.transpose(np.matrix(x_vals))
ones_column = np.transpose(np.matrix(np.repeat(a=1, repeats=100)))
X = np.column_stack((x_vals_column, ones_column))
Y = np.transpose(np.matrix(y_vals))
X_tensor = tf.constant(X, dtype=tf.float64)
Y_tensor = tf.constant(Y, dtype=tf.float64)
# Perform computations
tX_X = tf.matmul(tf.transpose(X_tensor), X_tensor)
L = tf.linalg.cholesky(tX_X)
tX_Y = tf.matmul(tf.transpose(X_tensor), Y_tensor)
sol1 = tf.linalg.solve(L, tX_Y)
sol2 = tf.linalg.solve(tf.transpose(L), sol1)
# Extract coefficients
solution_eval = sol2.numpy()
m_slope = solution_eval[0][0]
b_intercept = solution_eval[1][0]
print(''slope (m): '' + str(m_slope))
print(''intercept (b): '' + str(b_intercept))
# Visualization
best_fit = []
for i in x_vals:
best_fit.append(m_slope * i + b_intercept)
plt.plot(x_vals, y_vals, ''o'', label=''Data'')
plt.plot(x_vals, best_fit, ''r-'', label=''Linear Regression'', linewidth=3)
plt.legend(loc=''upper left'')
plt.show() PyTorch', '[-0.074262,-0.085566,0.025617,-0.019812,0.004961,-0.001013,0.030955,0.053120,-0.027287,0.008202,0.081222,-0.053184,0.066666,-0.027049,-0.083143,0.049807,-0.048609,0.025950,-0.030390,-0.026999,0.034734,-0.036662,-0.084841,0.027350,-0.044606,0.034452,-0.039960,-0.025958,0.006515,-0.094673,0.069308,0.105395,-0.030152,-0.016452,-0.007108,-0.007648,-0.101350,-0.003928,-0.002365,0.089920,-0.076106,0.025388,0.046413,-0.004974,0.015385,-0.067047,-0.044524,0.014048,-0.078660,-0.027562,-0.044304,0.047947,-0.044861,-0.010980,-0.018288,0.055002,0.040150,-0.031942,-0.018369,-0.050702,0.055416,0.033278,-0.090786,-0.000590,0.061207,0.047389,0.108813,-0.021995,0.089289,0.129215,-0.050499,0.039595,-0.041143,-0.048207,0.001883,-0.015672,0.028501,0.040734,0.036691,-0.031899,0.054916,-0.002938,0.010526,-0.016782,0.029854,0.036536,0.051882,0.037482,0.042275,-0.015541,0.112431,-0.004089,-0.145500,0.050161,0.035868,0.068059,-0.004365,-0.000750,0.102767,0.144157,-0.063667,0.009494,-0.019991,0.027077,-0.070830,-0.025189,0.010109,0.007290,-0.028769,0.011706,0.010413,0.013051,-0.014987,0.032457,0.062572,-0.107339,0.000831,0.007626,0.033672,0.034647,-0.024198,0.043146,-0.009506,0.163319,0.086787,-0.105637,-0.043587,-0.052128,0.002835,-0.056110,0.047993,-0.066604,-0.014332,0.070534,0.006063,-0.009262,0.010571,0.055147,-0.035245,0.021774,-0.057302,0.048154,0.003569,0.007498,0.078828,0.070886,-0.039406,-0.063245,0.034322,-0.026920,0.003439,-0.102426,-0.043812,-0.009276,-0.074626,0.039935,0.037277,-0.015483,0.011712,0.028755,-0.084464,0.066427,0.034158,-0.018761,0.047695,0.038187,0.030327,0.033550,-0.059836,0.058115,0.089848,-0.022435,-0.058901,-0.009130,0.083422,0.002222,-0.095498,-0.017030,-0.023604,0.019447,0.026243,-0.026145,0.013933,0.032330,-0.092255,-0.002261,0.022845,0.057210,-0.103452,-0.043422,-0.023780,-0.099961,0.027049,0.008803,-0.103105,-0.098562,0.138393,0.092941,-0.015062,0.004146,-0.035873,0.042145,0.049626,-0.048053,0.004484,0.025402,-0.013907,-0.100206,-0.0