INSERT INTO chunks (url, title, lang, published, chunk_index, content, embedding) VALUES ('https://alexisalulema.com/es/blog/descomposicion-cholesky-para-regresion-lineal/', 'Descomposición Cholesky para Regresión Lineal', 'es', '2023-10-03', 3, 'Numpy import matplotlib.pyplot as plt
import numpy as np
# Generate data
x_vals = np.linspace(start=0, stop=10, num=100)
y_vals = x_vals + np.random.normal(loc=0, scale=1, size=100)
x_vals_column = np.transpose(np.matrix(x_vals))
ones_column = np.transpose(np.matrix(np.repeat(a=1, repeats=100)))
X = np.column_stack((x_vals_column, ones_column))
Y = np.transpose(np.matrix(y_vals))
# Perform computations using Cholesky Decomposition
tX_X = np.dot(X.T, X)
L = np.linalg.cholesky(tX_X)
tX_Y = np.dot(X.T, Y)
sol = np.linalg.solve(L, tX_Y)
beta = np.linalg.solve(L.T, sol)
# Extract coefficients
m_slope = beta[0,0]
b_intercept = beta[1,0]
print(''slope (m): '' + str(m_slope))
print(''intercept (b): '' + str(b_intercept))
# Visualization
best_fit = []
for i in x_vals:
best_fit.append(m_slope * i + b_intercept)
plt.plot(x_vals, y_vals, ''o'', label=''Data'')
plt.plot(x_vals, best_fit, ''r-'', label=''Linear Regression'', linewidth=3)
plt.legend(loc=''upper left'')
plt.show() slope (m): 1.0830263227926582 intercept (b): -0.3348165868955632 Como se puede observar, esta solución es muy similar a la Regresión Lineal de Mínimos Cuadrados, pero esta descomposición es a veces mucho más eficiente y numéricamente estable.', '[-0.091004,-0.071317,-0.003828,-0.023018,-0.008413,0.005379,0.006716,0.049800,-0.035908,0.015134,0.082490,-0.029574,0.091178,0.003440,-0.086634,0.038924,-0.034969,0.014896,-0.038297,-0.030181,-0.006468,-0.043522,-0.056684,0.050144,-0.033426,0.048074,-0.028823,-0.018544,-0.004965,-0.079142,0.061102,0.100882,0.006478,-0.022752,-0.012515,-0.005567,-0.102552,0.024922,0.015740,0.068027,-0.077297,0.046973,0.049865,-0.004841,0.048327,-0.041565,-0.057773,0.005095,-0.050598,-0.005299,-0.064529,0.031183,-0.050652,-0.025997,-0.002714,0.034419,0.004532,-0.027005,-0.014778,-0.019966,0.082063,0.032255,-0.085212,-0.011673,0.073275,0.048438,0.155103,-0.052507,0.087258,0.133843,-0.064163,0.041144,-0.011200,-0.047252,-0.016440,-0.012642,0.016615,0.033909,0.018807,-0.017197,0.035905,0.000252,0.010153,-0.021863,0.010384,0.027476,0.065212,0.030887,0.076332,-0.041573,0.109194,0.011176,-0.178369,0.031754,0.025898,0.054925,-0.016057,0.001400,0.085999,0.158978,-0.056416,0.007322,-0.041190,-0.002822,-0.062543,-0.013777,0.025037,-0.007119,-0.031603,0.037938,0.045461,-0.003970,-0.008032,0.049594,0.092567,-0.095819,0.003883,0.000876,0.023897,0.038531,-0.002232,0.017354,0.019697,0.157048,0.097599,-0.109929,-0.021722,-0.050556,0.002185,-0.020215,0.059610,-0.041335,-0.014174,0.058675,-0.035908,-0.015947,0.000832,0.065355,-0.059682,0.027393,-0.050348,0.074004,0.022824,0.011109,0.074741,0.068357,-0.055626,-0.044776,0.043853,-0.062038,0.015779,-0.109302,-0.034702,-0.011000,-0.052370,0.045611,0.024796,0.001794,-0.005624,0.022330,-0.103658,0.060992,0.037754,-0.028069,0.046842,0.035405,0.007087,0.003298,-0.064570,0.073383,0.071873,-0.065462,-0.021348,-0.021050,0.081117,0.009845,-0.055384,-0.019910,-0.017090,0.024457,0.002423,-0.040971,0.006277,0.03218